"""Pydantic models for `harness.yaml` — the user-facing harness configuration.

Validated against `schemas/config.schema.json`. The schema is regenerated from these
models via `python -m harness.config.models export-schema`.
"""

from __future__ import annotations

from typing import Annotated, Literal

from pydantic import BaseModel, ConfigDict, Field, model_validator

# ---- enums (string literals so YAML reads cleanly) -------------------------

# Roles dropped from v0.2 — composer no longer loads `templates/roles/<role>/`
# overlays. Stacks are framework + paths; rules and skills emit purely from
# base + stacks + integrations + governance layers.
#
# Frameworks are open-ended. Composer auto-synthesises a `<framework>-patterns`
# skill scaffold for any framework name; team fills the body.
StackFramework = Annotated[str, Field(pattern=r"^[a-z][a-z0-9-]*$", min_length=1, max_length=64)]
# Package manager and test runner are open-ended too. Wizard collects whatever
# the user types. Common values: pnpm/npm/yarn/bun, uv/pip/poetry, go, cargo,
# gradle, maven, dotnet — but any string is accepted.
PackageManager = Annotated[str, Field(pattern=r"^[a-zA-Z][a-zA-Z0-9_./+-]*$", min_length=1, max_length=64)]
TestRunner = Annotated[str, Field(pattern=r"^[a-zA-Z][a-zA-Z0-9_./+-]*$", min_length=1, max_length=64)]
DocTracker = Literal["local", "confluence", "notion"]
IssueTracker = Literal["jira", "linear", "github", "azure-devops", "none"]
DesignTool = Literal["figma", "stitch", "claude-design", "html-mockup", "none"]
Vcs = Literal["github", "gitlab", "bitbucket", "azure-devops"]
Ci = Literal["github-actions", "gitlab-ci", "circleci", "jenkins", "azure-pipelines", "none"]
Observability = Literal["sentry", "datadog", "none"]
Comms = Literal["slack", "teams", "none"]
Target = Literal["claude-code", "codex", "copilot", "gemini", "cursor", "antigravity"]
GovernanceProfile = Literal["standard", "strict", "hipaa", "pci", "sox", "gdpr"]
ModelTier = Literal["opus", "sonnet", "haiku", "inherit"]
SdlcPhase = Literal[
    "intake", "research", "plan", "implement", "validate", "review", "ci-cd", "import"
]


# ---- sub-models -----------------------------------------------------------

class ProjectMeta(BaseModel):
    model_config = ConfigDict(extra="forbid")

    name: Annotated[str, Field(min_length=1, max_length=64, pattern=r"^[a-z][a-z0-9-]*$")]
    description: Annotated[str, Field(min_length=1, max_length=256)]
    repo_root: str = "."
    author: dict[str, str] | None = None  # {name, email, url}


class StackSpec(BaseModel):
    model_config = ConfigDict(extra="forbid")

    id: Annotated[str, Field(pattern=r"^[a-z][a-z0-9-]*$")]
    framework: StackFramework
    version: str | None = None  # set by `harness init` from `name:version` syntax
    package_manager: PackageManager | None = None
    test_runner: TestRunner | None = None
    paths: list[str] = Field(default_factory=list)


class SdlcConfig(BaseModel):
    model_config = ConfigDict(extra="forbid")

    phases: list[SdlcPhase] = Field(
        default_factory=lambda: [
            "intake", "research", "plan", "implement", "validate", "review", "ci-cd"
        ]
    )


class IntegrationsConfig(BaseModel):
    model_config = ConfigDict(extra="forbid")

    doc_tracker: DocTracker = "local"
    issue_tracker: IssueTracker = "none"
    design: DesignTool = "none"
    vcs: Vcs = "github"
    ci: Ci = "github-actions"
    observability: Observability = "none"
    comms: Comms = "none"


class GovernanceConfig(BaseModel):
    model_config = ConfigDict(extra="forbid")

    profile: GovernanceProfile = "standard"
    secret_scan: bool = True
    pii_scan_warn_only: bool = True


class DomainProfileSpec(BaseModel):
    """Schema for a custom domain profile stored in harness.yaml under domains.custom_profiles."""

    model_config = ConfigDict(extra="forbid")

    signals: list[str] = Field(default_factory=list)
    complexity: Literal["low", "medium", "high"] = "medium"
    key_concerns: list[str] = Field(default_factory=list)
    required_knowledge: list[str] = Field(default_factory=list)
    suggested_workflow: str = "domain-research"
    web_searches: list[str] = Field(default_factory=list)
    special_sections: list[str] = Field(default_factory=list)


class DomainsConfig(BaseModel):
    """Explicit domain opt-in. selected=[] means no domain behavior (zero drift)."""

    model_config = ConfigDict(extra="forbid")

    selected: list[str] = Field(default_factory=list)
    custom_profiles: dict[str, DomainProfileSpec] = Field(default_factory=dict)


class ModelRouting(BaseModel):
    model_config = ConfigDict(extra="forbid")

    default: ModelTier = "sonnet"
    agents: dict[str, ModelTier] = Field(default_factory=dict)


class PermissionsExtras(BaseModel):
    model_config = ConfigDict(extra="forbid")

    allow_extra: list[str] = Field(default_factory=list)
    deny_extra: list[str] = Field(default_factory=list)


class ClaudeCodeOutput(BaseModel):
    model_config = ConfigDict(extra="forbid")

    project_dir: str = ".claude"
    emit_mcp: bool = True
    emit_plugin: bool = False  # v2 — see plan §19


class ValidateOutput(BaseModel):
    """Tunables for /arh-validate-feature behaviour."""

    model_config = ConfigDict(extra="forbid")

    retry_count: Annotated[int, Field(ge=0, le=5)] = 2
    """Max retry attempts per FAILed/ERRORed TC in Phase 3 (V1 flake detection).
    0 disables retries — every flake counts as a real failure.
    Capped at 5 to prevent runaway CI cost."""

    stack_smoke: bool = True
    """Run the stack-smoke gate in Phase 2b (start app → migrate → /health → kill).
    Default true. Set false for stacks with no runnable surface (pure library),
    or in CI where smoke runs as a separate dedicated job."""


class OutputsConfig(BaseModel):
    model_config = ConfigDict(extra="forbid")

    claude_code: ClaudeCodeOutput = Field(default_factory=ClaudeCodeOutput)
    validation: ValidateOutput = Field(default_factory=ValidateOutput)


class HarnessConfig(BaseModel):
    """Top-level shape of `harness.yaml`."""

    model_config = ConfigDict(extra="forbid")

    apiVersion: Literal["harness.dev/v1"] = "harness.dev/v1"  # noqa: N815 — YAML key
    kind: Literal["Harness"] = "Harness"
    template_version: Annotated[str, Field(pattern=r"^\d+\.\d+\.\d+$")] = "0.1.0"

    project: ProjectMeta
    stacks: list[StackSpec] = Field(default_factory=list)
    sdlc: SdlcConfig = Field(default_factory=SdlcConfig)
    integrations: IntegrationsConfig = Field(default_factory=IntegrationsConfig)
    governance: GovernanceConfig = Field(default_factory=GovernanceConfig)
    domains: DomainsConfig = Field(default_factory=DomainsConfig)
    model_routing: ModelRouting = Field(default_factory=ModelRouting)
    permissions: PermissionsExtras = Field(default_factory=PermissionsExtras)
    targets: list[Target] = Field(default_factory=lambda: ["claude-code"])
    outputs: OutputsConfig = Field(default_factory=OutputsConfig)

    # ---- cross-field validation ----

    @model_validator(mode="after")
    def _stack_ids_unique(self) -> HarnessConfig:
        ids = [s.id for s in self.stacks]
        if len(set(ids)) != len(ids):
            raise ValueError("stack ids must be unique")
        return self

    @model_validator(mode="after")
    def _v1_targets_only_claude_code(self) -> HarnessConfig:
        non_v1 = [t for t in self.targets if t != "claude-code"]
        if non_v1:
            raise ValueError(
                f"v1 supports only target 'claude-code'; deferred: {non_v1}. See plan §3."
            )
        return self
